                      << arg << "'\n"
                      << usage;
            return 2;
        }
    }

    if (!opts.haveKeyHex) {
        std::cerr << "messagetag " << command
                  << ": error: missing required option '--key-hex'\n"
                  << usage;
        return 2;
    }
    if (!opts.haveFile) {
        std::cerr << "messagetag " << command
                  << ": error: missing required option '--file'\n"
                  << usage;
